from collections import Counter
import itertools


def task_func(d):
    """Count occurrences of each integer across all list values of dictionary d."""
    return dict(Counter(itertools.chain.from_iterable(d.values())))


if __name__ == "__main__":
    example = {"a": [1, 2, 3], "b": [2, 3, 4], "c": [3, 4, 5]}
    print(task_func(example))  # {1: 1, 2: 2, 3: 3, 4: 2, 5: 1}
```

The function chains all the list values together with `itertools.chain.from_iterable`, counts the integers with `Counter`, and returns the result as a regular dictionary.
